          "html": "Добавить человеческий смысл операции — ещё одна задача. Сообщение «read failed» менее полезно, чем «не удалось загрузить настройки профиля». Но замена одной строки другой не должна бесследно уничтожать исходную причину. Для связки внешнего контекста с причиной существует <code>std::throw_with_nested</code>; полный разбор будет в разделе «Сохраняем причину ошибки без повторяющихся логов». Здесь достаточно различать три действия: продолжить исходное исключение, сохранить его для последующей обработки или создать внешнюю ошибку со связанной причиной."
