          "html": "<strong>Что находится под этим механизмом.</strong> Стандарт задаёт наблюдаемый порядок создания, очистки и входа в обработчик, но не требует единственного внутреннего алгоритма поиска catch. ABI (соглашение о двоичном взаимодействии компилятора и среды выполнения) может задавать таблицы и служебные вызовы конкретной платформы."
