          "code": "int getValue() const noexcept { return value_; }  // обещаем не бросать\n\nvoid swap(Widget& other) noexcept {               // условие примера: a_ и b_ имеют тип int\n    std::swap(a_, other.a_);\n    std::swap(b_, other.b_);\n}"
