          "answer": "Прежнее состояние. Пока весь новый индекс не готов, state_ не меняется. Next владеет новым State; при выходе по исключению готовые контейнеры уничтожаются и освобождают свои ресурсы. Важно именно разделение старого и нового состояния, а не количество уже успешно вставленных новых имён."
