          "type": "text",
          "html": "<strong>Почему перенос в новый буфер сложнее обычного чтения?</strong> Пусть нужно создать новые элементы из пяти старых. Копирование, соответствующее своему договору, читает источник. При отказе на четвёртом элементе созданные копии можно убрать, не меняя старые. Перемещение же может забирать ресурсы из источников: после отказа часть старых элементов уже изменена. Поэтому возможность броска влияет на безопасную стратегию."
