          "answer": "Критерий здесь — не обещание, что новая копия обязательно создастся. Корректное копирование позволяет оставить источник прежним при подготовке. Если создание новой копии откажет, уже готовые временные объекты можно убрать, сохранив старые. Для всей операции ещё нужно проверить остальные действия и договор типа."
