          "type": "text",
          "html": "Чтобы увидеть различие без сети, построим намеренно маленькую модель. Объект <code>RemoteModel</code> будет изображать исполнителя, а <code>confirmed</code> — знание вызывающего о результате. Метод сначала меняет своё поле, затем сообщает исключение о потерянном ответе."
