          "answer": "Нет. Гарантия для очереди описывает её собственное состояние. Исполнитель мог применить действие до потери ответа. Для внешнего эффекта нужны отдельные сведения: подтверждение, проверка состояния или договор обработки повторов. Один локальный catch этих сведений не создаёт."
