          "type": "text",
          "html": "Другая задача — заменить видимую версию файла, не показывая читателю половину нового содержимого. Для успешного <code>rename</code> в Linux замена существующего имени атомарна в документированном смысле: другой процесс не увидит момент отсутствия этого целевого имени. Но это свойство не доказывает сохранность новой версии после отключения питания. Старые уже открытые файловые дескрипторы тоже не превращаются автоматически в доступ к новому содержимому."
